                        ctx.next()?;
                        ctx.mes("[Liotzburg]")?;
                        ctx.mes("Why waste money?")?;
                        ctx.mes("We haven't had any")?;
                        ctx.mes("problems so far! Look,")?;
                        ctx.mes("everything's fine! Why")?;
                        ctx.mes("are you exaggerating")?;
                        ctx.mes("such small details?")?;
                        ctx.next()?;
                        ctx.mes("[Liotzburg]")?;
